return [{json:{
  spmBaseUrl:     'https://api.YOUR_SPM_REGION.signavio.cloud.sap',
  spmTenantId:    'YOUR_SPM_TENANT_ID',
  spmDirectory:   '/directory/YOUR_SPM_DIRECTORY_ID',
  spmUser:        'YOUR_SPM_USER',
  spmPassword:    'YOUR_SPM_PASSWORD',
  aiDeploymentId: 'YOUR_AI_CORE_DEPLOYMENT_ID',
  targetLanguage: 'German'
}}];

const aiOutput = $input.first().json.response || $input.first().json.output || $input.first().json.text || '';
let translatedTexts;

try {
  const cleanContent = aiOutput.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  translatedTexts = JSON.parse(cleanContent);
  if (!Array.isArray(translatedTexts)) throw new Error('Translation result is not an array');
} catch (error) {
  return [{json: {error: true, reason: 'Failed to parse AI response', details: error.message, rawOutput: aiOutput}}];
}

const processName = $('Parse Texts').first().json.processName || 'BPMN Process';
const targetLang = $('Config').first().json.targetLanguage || 'German';
const originalXml = $('Parse Texts').first().json.originalXml;
const textsToTranslate = $('Parse Texts').first().json.textsToTranslate;

if (translatedTexts.length !== textsToTranslate.length) {
  return [{json: {error: true, reason: 'Translation count mismatch', expected: textsToTranslate.length, received: translatedTexts.length}}];
}

let translatedXml = originalXml;
for (let i = 0; i < textsToTranslate.length; i++) {
  const original = textsToTranslate[i];
  const translated = translatedTexts[i];
  const escapedOriginal = original.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  translatedXml = translatedXml.replace(new RegExp(escapedOriginal, 'g'), translated);
}

// Restore definitions name so SPM uses the correct model name
const desiredName = processName + ' (' + targetLang + ')';
translatedXml = translatedXml.replace(
  /(<definitions[^>]+name=")[^"]*"/,
  function(match, pre) { return pre + desiredName + '"'; }
);


// Replace definitions id with a fresh one so SPM treats it as a new model
translatedXml = translatedXml.replace(
  /(<definitions[^>]+id=")[^"]*"/,
  function(match, pre) { return pre + '_' + Math.random().toString(36).substr(2,9) + '-' + Math.random().toString(36).substr(2,9) + '"'; }
);

// Override BPMNDiagram name so SPM displays the correct model name
translatedXml = translatedXml.replace(
  /(<bpmndi:BPMNDiagram[^>]+name=")[^"]*"/,
  function(match, pre) { return pre + desiredName + '"'; }
);
const buffer = Buffer.from(translatedXml, 'utf-8');

return [{json: {translationComplete: true, originalTextCount: textsToTranslate.length, translatedTextCount: translatedTexts.length, modelName: processName, targetLang: targetLang}, binary: {data: {data: buffer.toString('base64'), mimeType: 'application/xml', fileName: (processName + ' (' + targetLang + ')').replace(/[\/\\?%*:|"<>]/g, '-') + '.bpmn'}}}];

const resp=$input.first().json;
const cookies=resp.headers?.['set-cookie']||[];
const list=Array.isArray(cookies)?cookies:[cookies];
let jsessionId='',token='';
for(const c of list){
  const j=c.match(/JSESSIONID=([^;]+)/);if(j)jsessionId=j[1];
  const t=c.match(/^token=([^;]+)/);if(t)token=t[1];
}
const translateItem=$('Apply Translations').first();
const bin=translateItem.binary?.data;
console.log('binary id:'+bin?.id+' dataLen:'+bin?.data?.length+' fileSize:'+bin?.fileSize);
return [{json:{jsessionId,token},binary:translateItem.binary}];

const resp=$input.first().json;
const raw=resp.data||resp.body||resp;
let d;
try{ d=typeof raw==='string'?JSON.parse(raw):raw; }catch(e){ d={}; }
const modelId=d.mainModelId||(d.createdIds||[])[0]||null;
console.log('modelId:'+modelId);
if(modelId) return [{json:{status:'success',modelId,spmUrl:'https://YOUR_SPM_HOST/p/hub/model/'+modelId+'?mode=preview'}}];
return [{json:{status:'failed',response:d}}];

const cfg = $('Config').first().json;
const logDone = $('Log Done').first().json;
const applied = $('Apply Translations').first().json;
const webhookBody = $('Webhook').first().json.body || $('Webhook').first().json;

const lang = cfg.targetLanguage || 'German';
const modelId = logDone.modelId && logDone.modelId !== '?' ? logDone.modelId : null;
const count = applied.translatedTextCount || 0;
const spmUrl = logDone.spmUrl || '';
const modelName = webhookBody.modelName || applied.modelName || '';

const spmLine = modelId
  ? `<a href="${spmUrl}">Open Translated Model in SPM</a>`
  : '<b>⚠️ SPM Import failed</b>';

const nameLine = modelName ? `<b>Model:</b> ${modelName}<br>` : '';

const message = `<p>🔄 <b>BPMN Translation Ready for Review</b></p>
<p>${nameLine}<b>Language:</b> ${lang}<br>
<b>Elements translated:</b> ${count}</p>
<p>📄 ${spmLine}</p>
<p>Please review the model and submit for approval in SPM.</p>`;

return [{ json: { message, modelId, lang } }];

// Get XML content from the HTTP response
const webhookBody = $('Webhook').first().json.body || $('Webhook').first().json;
const xmlContent = webhookBody.xmlContent || '';
const item = { json: { xmlContent } };

if (!xmlContent || xmlContent.length < 50) {
  console.error('No valid XML content received');
  console.log('Available keys:', Object.keys(item.json));
  return [{json: {
    error: true,
    reason: 'No XML content in response',
    availableKeys: Object.keys(item.json),
    preview: xmlContent.substring(0, 100)
  }}];
}

console.log('XML content length:', xmlContent.length);
console.log('XML preview:', xmlContent.substring(0, 200));

// Parse XML to extract text from name attributes in BPMN elements
// Signavio stores translatable text in name="" attributes, not element content

// Extract process name directly from <process name="...">
const payloadModelName = webhookBody.modelName || '';
const processNameMatch = xmlContent.match(/<(?:[a-zA-Z0-9]+:)?process[^>]+\sname="([^"]+)"/);
const processName = payloadModelName || (processNameMatch ? processNameMatch[1] : 'BPMN Process');
console.log('Process name:', processName);
const patterns = [
  // name attribute on any BPMN element (tasks, events, gateways, etc.)
  /\sname="([^"]+)"/g,
  // text content inside bpmn:text or signavio:label elements (fallback)
  /<(?:bpmn:)?text>([^<]+)<\/(?:bpmn:)?text>/g,
  /<(?:signavio:)?label>([^<]+)<\/(?:signavio:)?label>/g,
  // documentation elements
  /<(?:bpmn:)?documentation>([^<]+)<\/(?:bpmn:)?documentation>/g,
  // i18n:translation elements
  /<i18n:translation[^>]*>([^<]+)<\/i18n:translation>/g
];

const textElements = [];
const seen = new Set(); // Avoid duplicates

for (const pattern of patterns) {
  let match;
  while ((match = pattern.exec(xmlContent)) !== null) {
    const text = match[1];
    if (text && text.trim() && !seen.has(text.trim())) {
      // Skip technical/system values (UUIDs, URLs, namespaces)
      if (text.includes('://') || text.match(/^[a-f0-9-]{36}$/i) || text.startsWith('sid-')) {
        continue;
      }
      textElements.push(text.trim());
      seen.add(text.trim());
    }
  }
}

console.log('Extracted ' + textElements.length + ' text elements');
if (textElements.length > 0) {
  console.log('Sample texts:', textElements.slice(0, 5));
}

if (textElements.length === 0) {
  console.warn('No translatable text found in BPMN');
  // Show more of the XML to help debug
  return [{json: {
    error: true,
    reason: 'No text elements found in BPMN',
    xmlPreview: xmlContent.substring(0, 1000),
    hint: 'Check if XML uses namespaces or different tag names'
  }}];
}

const targetLang = $('Config').first().json.targetLanguage || 'Spanish';
const chatInput = `Translate these ${textElements.length} BPMN element names to ${targetLang}. Return ONLY a JSON array of ${textElements.length} translations in the same order:\n\n${JSON.stringify(textElements, null, 2)}`;

// Convert XML to binary for later import
const buffer = Buffer.from(xmlContent, 'utf-8');
const base64Data = buffer.toString('base64');

return [{
  json: {
    processName,
    originalXml: xmlContent,
    textsToTranslate: textElements,
    textCount: textElements.length,
    chatInput: chatInput
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: 'application/xml',
      fileName: 'original.bpmn'
    }
  }
}];
